INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4575834, 658679, 30712, '<td valign="top">It''s the simplicity of this scene that appeals to me.  I love the arrangement of the deer.</td>', 'It''s the simplicity of this scene that appeals to me.  I love the arrangement of the deer.', '2008-03-20 03:07:30.000000', NULL, 1),
(4575835, 659479, 30712, '<td valign="top">A great shot.  As a painter I find this an inspiring use of colour and shape.</td>', 'A great shot.  As a painter I find this an inspiring use of colour and shape.', '2008-03-20 03:10:51.000000', NULL, 1),
(4575841, 659136, 5364, '<td valign="top">It''s a good idea and the composition is good, but the lighting lets you down - what looks like flash just makes every thing look very flat.</td>', 'It''s a good idea and the composition is good, but the lighting lets you down - what looks like flash just makes every thing look very flat.', '2008-03-20 03:36:34.000000', NULL, 1),
(4575845, 659224, 5364, '<td valign="top">Great quality photo, but I''m not keen on a composition that has a strand of wire that close to the bottom edge of the frame.</td>', 'Great quality photo, but I''m not keen on a composition that has a strand of wire that close to the bottom edge of the frame.', '2008-03-20 03:42:18.000000', NULL, 1),
(4575848, 659280, 5364, '<td valign="top">This has some potential - what does it look like in monochrome? However it all looks a bit out of focus or shaky.</td>', 'This has some potential - what does it look like in monochrome? However it all looks a bit out of focus or shaky.', '2008-03-20 03:46:17.000000', NULL, 1),
(4575850, 658506, 5364, '<td valign="top">I''m not keen on the composition - having the signpost right in the middle - I think I might have had it on the right hand side instead.</td>', 'I''m not keen on the composition - having the signpost right in the middle - I think I might have had it on the right hand side instead.', '2008-03-20 03:50:19.000000', NULL, 1),
(4575947, 659609, 86799, '<td valign="top">Nice lighting on the sand, the low angle gives nice curves.  Great texture.  Very pretty.</td>', 'Nice lighting on the sand, the low angle gives nice curves.  Great texture.  Very pretty.', '2008-03-20 05:51:17.000000', NULL, 1),
(4575948, 659492, 86799, '<td valign="top">Nice, but a little harsh looking.  Maybe a little less contrast / sharpening.</td>', 'Nice, but a little harsh looking.  Maybe a little less contrast / sharpening.', '2008-03-20 05:52:23.000000', NULL, 1),
(4575949, 658601, 66709, '<td valign="top">Seaside never can be off Season!!!</td>', 'Seaside never can be off Season!!!', '2008-03-20 05:52:50.000000', NULL, 1),
(4575951, 659433, 86799, '<td valign="top">Spring!  I like this, simple, pretty.</td>', 'Spring!  I like this, simple, pretty.', '2008-03-20 05:57:11.000000', NULL, 1),
(4575952, 659547, 86799, '<td valign="top">Some DOF would have made this pop.</td>', 'Some DOF would have made this pop.', '2008-03-20 05:58:59.000000', NULL, 1),
(4575953, 659207, 86799, '<td valign="top">Gotta love spring flowers!  Nice, but needs closer POV, more detail, maybe lower angle.  Looks a bit snapshot-ish at this angle.</td>', 'Gotta love spring flowers!  Nice, but needs closer POV, more detail, maybe lower angle.  Looks a bit snapshot-ish at this angle.', '2008-03-20 06:01:33.000000', NULL, 1),
(4575958, 659155, 86799, '<td valign="top">Good colors, nice contrast on the newer wire.  The spider web detail is great.  Smooth and sharp at the same time.</td>', 'Good colors, nice contrast on the newer wire.  The spider web detail is great.  Smooth and sharp at the same time.', '2008-03-20 06:09:45.000000', NULL, 1),
(4576066, 659195, 88010, '<td valign="top">A tad bit dark, the whites should POP.</td>', 'A tad bit dark, the whites should POP.', '2008-03-20 07:21:12.000000', NULL, 1),
(4576070, 659529, 88010, '<td valign="top">Is this about the fence or the dog. It seems more about the dog because has center stage. I would crop off the bottom leaving the dog in the pic, bbut at the bottom and less important, then it becomes all about the fence.</td>', 'Is this about the fence or the dog. It seems more about the dog because has center stage. I would crop off the bottom leaving the dog in the pic, bbut at the bottom and less important, then it becomes all about the fence.', '2008-03-20 07:22:34.000000', NULL, 1),
(4576074, 659420, 88010, '<td valign="top">The pic sems to be more about the flowers than the fence.</td>', 'The pic sems to be more about the flowers than the fence.', '2008-03-20 07:23:30.000000', NULL, 1),
(4576080, 659680, 88010, '<td valign="top">Too much sky, the photo contains 80% sky and so this is what this picture is about. To make it about the fence, crop out all but small portion of the sky. Then it''s all about the fence.</td>', 'Too much sky, the photo contains 80% sky and so this is what this picture is about. To make it about the fence, crop out all but small portion of the sky. Then it''s all about the fence.', '2008-03-20 07:25:21.000000', NULL, 1),
(4576082, 659521, 88010, '<td valign="top">This is about a horse. the fence has no real importance to the viewer.</td>', 'This is about a horse. the fence has no real importance to the viewer.', '2008-03-20 07:26:11.000000', NULL, 1),
(4576087, 658988, 88010, '<td valign="top">Very nice...all about the fence, no distractions. well composed , interesting DOF. Good job.</td>', 'Very nice...all about the fence, no distractions. well composed , interesting DOF. Good job.', '2008-03-20 07:27:36.000000', NULL, 1),
(4576092, 658346, 88010, '<td valign="top">Yup there is a fence. But the main focal point is the road.</td>', 'Yup there is a fence. But the main focal point is the road.', '2008-03-20 07:29:00.000000', NULL, 1),
(4576097, 659233, 88010, '<td valign="top">Good dof, keeps the eye on the fence. We know what is in the background, but the selective focus keeps our attention where YOU put it.<br/> <br/>Nice.</td>', 'Good dof, keeps the eye on the fence. We know what is in the background, but the selective focus keeps our attention where YOU put it. Nice.', '2008-03-20 07:30:57.000000', NULL, 1),
(4576098, 659611, 88010, '<td valign="top">Too much vignetting.</td>', 'Too much vignetting.', '2008-03-20 07:32:04.000000', NULL, 1),
