(4577222, 659102, 88054, '<td valign="top">Beautiful photo. A little dark in the upper left corner but very nicely composed.</td>', 'Beautiful photo. A little dark in the upper left corner but very nicely composed.', '2008-03-20 15:27:15.000000', NULL, 1),
