(4577249, 658928, 86799, '<td valign="top">Nice idea, but the pose doesn''t look very natural, and the hanging down sweatshirt is a distraction.</td>', 'Nice idea, but the pose doesn''t look very natural, and the hanging down sweatshirt is a distraction.', '2008-03-20 15:34:45.000000', NULL, 1),
(4577252, 659528, 15407, '<td valign="top">First glance made me think oh no, then I realized that the rotation really adds to the photo!</td>', 'First glance made me think oh no, then I realized that the rotation really adds to the photo!', '2008-03-20 15:36:01.000000', NULL, 1),
(4577253, 658244, 88054, '<td valign="top">Beautiful shot. A little too tight on the cropping for me. I would like to see just a bit more room on the top and bottom. The barb feels cramped. More on the bottom would give the rain drop somewhere to fall. The orange glow on the bottom of the wire seems unnatural (Direct Flash?). Great idea, great focus. Good luck.</td>', 'Beautiful shot. A little too tight on the cropping for me. I would like to see just a bit more room on the top and bottom. The barb feels cramped. More on the bottom would give the rain drop somewhere to fall. The orange glow on the bottom of the wire seems unnatural (Direct Flash?). Great idea, great focus. Good luck.', '2008-03-20 15:36:17.000000', NULL, 1),
(4577255, 657987, 86799, '<td valign="top">Idea is good, but you need an more interesting subject back there in the knothole.</td>', 'Idea is good, but you need an more interesting subject back there in the knothole.', '2008-03-20 15:36:22.000000', NULL, 1),
(4577256, 659617, 73056, '<td valign="top">I really love the composition and colorless look to this photo. It''s a wonderful abstract.</td>', 'I really love the composition and colorless look to this photo. It''s a wonderful abstract.', '2008-03-20 15:36:29.000000', NULL, 1),
(4577264, 659218, 15407, '<td valign="top">To bad it couldn''t be entered in the "Diamond" orientation.</td>', 'To bad it couldn''t be entered in the "Diamond" orientation.', '2008-03-20 15:38:04.000000', NULL, 1),
(4577269, 659682, 15407, '<td valign="top">A nice fences... goes with the flow! I wonder what it would have looked like with the sun coming in from the opposite direction?</td>', 'A nice fences... goes with the flow! I wonder what it would have looked like with the sun coming in from the opposite direction?', '2008-03-20 15:39:54.000000', NULL, 1),
(4577278, 658238, 15407, '<td valign="top">Nice Lighting and processing ... bit much on the sharpening though.</td>', 'Nice Lighting and processing ... bit much on the sharpening though.', '2008-03-20 15:42:25.000000', NULL, 1),
(4577279, 658060, 88054, '<td valign="top">Beautiful colors. Edges seem faded (vignettes or lens hood?). Not sure if we can do that in basic editing. Still a gorgeous shot. Good luck.</td>', 'Beautiful colors. Edges seem faded (vignettes or lens hood?). Not sure if we can do that in basic editing. Still a gorgeous shot. Good luck.', '2008-03-20 15:42:54.000000', NULL, 1),
(4577282, 659145, 15407, '<td valign="top">The weed fence,,, doing a nice job of it too.</td>', 'The weed fence,,, doing a nice job of it too.', '2008-03-20 15:43:15.000000', NULL, 1),
(4577298, 657370, 15407, '<td valign="top">Think maybe a tighter crop off of the top might have helped.</td>', 'Think maybe a tighter crop off of the top might have helped.', '2008-03-20 15:48:01.000000', NULL, 1),
(4577346, 659493, 15407, '<td valign="top">I found the picture a little too dark.  I like the idea of the hedgerow although the detail is lost in the darkness.  Perhaps a tighter crop and a lightening of the the hedgerow would have helped.</td>', 'I found the picture a little too dark.  I like the idea of the hedgerow although the detail is lost in the darkness.  Perhaps a tighter crop and a lightening of the the hedgerow would have helped.', '2008-03-20 16:15:34.000000', NULL, 1),
(4577353, 659661, 15407, '<td valign="top">It has not held back her alure...</td>', 'It has not held back her alure...', '2008-03-20 16:18:20.000000', NULL, 1),
