(4577363, 659075, 15407, '<td valign="top">Nature will win every time!</td>', 'Nature will win every time!', '2008-03-20 16:27:21.000000', NULL, 1),
(4577509, 657765, 73056, '<td valign="top">Bleak and nice, great simple lines and wonderful composition. I love how subjects like this can turn into art through the right eye. However, I will say, I wish the processing had more level contrast between the light and dark tones.</td>', 'Bleak and nice, great simple lines and wonderful composition. I love how subjects like this can turn into art through the right eye. However, I will say, I wish the processing had more level contrast between the light and dark tones.', '2008-03-20 18:10:20.000000', NULL, 1),
(4577511, 658265, 73056, '<td valign="top">Wow. This is a fence in your face. Powerful composition for the challenge subject.</td>', 'Wow. This is a fence in your face. Powerful composition for the challenge subject.', '2008-03-20 18:11:37.000000', NULL, 1),
(4577513, 658309, 73056, '<td valign="top">Lovely silhouette and leading lines.</td>', 'Lovely silhouette and leading lines.', '2008-03-20 18:12:22.000000', NULL, 1),
(4577515, 659194, 73056, '<td valign="top">Ilike this photo and its tonal quality.</td>', 'Ilike this photo and its tonal quality.', '2008-03-20 18:12:56.000000', NULL, 1),
