INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4577532, 657754, 73056, '<td valign="top">This is a lovely shot. Wish it were a little brighter with more contrast though.</td>', 'This is a lovely shot. Wish it were a little brighter with more contrast though.', '2008-03-20 18:24:06.000000', NULL, 1),
(4577535, 659145, 73056, '<td valign="top">Lovely composition to this.</td>', 'Lovely composition to this.', '2008-03-20 18:25:55.000000', NULL, 1),
(4577536, 659537, 73056, '<td valign="top">I like the composition on this and you''ve chosen the perfect tones for the subject.</td>', 'I like the composition on this and you''ve chosen the perfect tones for the subject.', '2008-03-20 18:27:02.000000', NULL, 1),
(4577540, 659118, 73056, '<td valign="top">Great angle. Very contemporary feeling. I would have cropped out the top background bit to where the walkway starts to curve for a total geometric/abstract feeling to this. Then I would have pumped the contrast up a notch. But that''s me. Really like it though.</td>', 'Great angle. Very contemporary feeling. I would have cropped out the top background bit to where the walkway starts to curve for a total geometric/abstract feeling to this. Then I would have pumped the contrast up a notch. But that''s me. Really like it though.', '2008-03-20 18:31:52.000000', NULL, 1),
(4577541, 659400, 73056, '<td valign="top">Love the abstract feeling to this.</td>', 'Love the abstract feeling to this.', '2008-03-20 18:34:11.000000', NULL, 1),
(4577542, 659651, 73056, '<td valign="top">Lovely landscape.</td>', 'Lovely landscape.', '2008-03-20 18:35:29.000000', NULL, 1),
(4577545, 659116, 73056, '<td valign="top">Beautiful shot. Surely at the top!</td>', 'Beautiful shot. Surely at the top!', '2008-03-20 18:39:28.000000', NULL, 1),
(4577546, 658705, 73056, '<td valign="top">Great shot and processing.</td>', 'Great shot and processing.', '2008-03-20 18:40:07.000000', NULL, 1),
(4577554, 659487, 73056, '<td valign="top">Beautiful composition. Love all that white.</td>', 'Beautiful composition. Love all that white.', '2008-03-20 18:45:03.000000', NULL, 1),
(4577605, 658601, 32011, '<td valign="top">Beautiful shot.  Great use of the fences as leading lines... would have greatly benefited by having someone on the beach or something in the water, but it''s not always possible to organise stuff like that when out and about taking photos.</td>', 'Beautiful shot.  Great use of the fences as leading lines... would have greatly benefited by having someone on the beach or something in the water, but it''s not always possible to organise stuff like that when out and about taking photos.', '2008-03-20 19:26:37.000000', NULL, 1),
(4577607, 659479, 32011, '<td valign="top">Nice.  Detail in the wood is good.  My is is constantly drawn to the large knot and the green section on the centre right of the image, making it a bit unbalanced.</td>', 'Nice.  Detail in the wood is good.  My is is constantly drawn to the large knot and the green section on the centre right of the image, making it a bit unbalanced.', '2008-03-20 19:28:53.000000', NULL, 1),
(4577610, 659181, 32011, '<td valign="top">This image would benefit from a tighter crop... or taken from a different angle.</td>', 'This image would benefit from a tighter crop... or taken from a different angle.', '2008-03-20 19:31:35.000000', NULL, 1),
(4577617, 659193, 91089, '<td valign="top">This photo is really great looking, it is bright, it has a great shine to it. But the people in the back ground really do take away from it. It is a great photo none the less.</td>', 'This photo is really great looking, it is bright, it has a great shine to it. But the people in the back ground really do take away from it. It is a great photo none the less.', '2008-03-20 19:38:14.000000', NULL, 1),
(4577619, 658185, 32011, '<td valign="top">Nice detail in the post which gets you in, then the leading lines of the post draws you into the image further, to the cross beam, which make a crucifix like image (appropriate considering I''m viewing this on Good Friday)... then one notices the other elements of the fence descending from the cross beam.  <br/> <br/>It''s a nice photo...  IMO the branches in the background are an issue, as is the angle of the cross beam... might have been an idea to straighten the image to the cross beam (though that may have thrown out the horizontals at the base of the post...)</td>', 'Nice detail in the post which gets you in, then the leading lines of the post draws you into the image further, to the cross beam, which make a crucifix like image (appropriate considering I''m viewing this on Good Friday)... then one notices the other elements of the fence descending from the cross beam.   It''s a nice photo...  IMO the branches in the background are an issue, as is the angle of the cross beam... might have been an idea to straighten the image to the cross beam (though that may have thrown out the horizontals at the base of the post...)', '2008-03-20 19:38:46.000000', NULL, 1),
(4577623, 658304, 91089, '<td valign="top">The pole in the background really doesn''t help the photo, but it does have a really cool look to this picture.</td>', 'The pole in the background really doesn''t help the photo, but it does have a really cool look to this picture.', '2008-03-20 19:41:25.000000', NULL, 1),
(4577624, 659673, 32011, '<td valign="top">I like the green tufts of grass and the concept, however I feel the DOF is too shallow... and even the first post looks a little OOF... just a fraction</td>', 'I like the green tufts of grass and the concept, however I feel the DOF is too shallow... and even the first post looks a little OOF... just a fraction', '2008-03-20 19:41:38.000000', NULL, 1),
(4577625, 659627, 14437, '<td valign="top">I like the dramatic lighting and the contrast between the blue sky and orange street light.</td>', 'I like the dramatic lighting and the contrast between the blue sky and orange street light.', '2008-03-20 19:41:44.000000', NULL, 1),
(4577627, 658244, 14437, '<td valign="top">I found the composition a little too tight. Otherwise a great shot.</td>', 'I found the composition a little too tight. Otherwise a great shot.', '2008-03-20 19:42:51.000000', NULL, 1),
(4577628, 658530, 14437, '<td valign="top">Very original. I like the sense and the composition.</td>', 'Very original. I like the sense and the composition.', '2008-03-20 19:43:02.000000', NULL, 1),
(4577630, 658680, 14437, '<td valign="top">A very interesting point of view.</td>', 'A very interesting point of view.', '2008-03-20 19:43:16.000000', NULL, 1),
