(4579022, 658950, 74209, '<td valign="top">I love the composition, mood, colors.  This is one of my very favorites in this competition.</td>', 'I love the composition, mood, colors.  This is one of my very favorites in this competition.', '2008-03-21 16:37:40.000000', NULL, 1),
(4579143, 659514, 45631, '<td valign="top">This is not an exceptional fence picture (the fence itself that is) but it works so well with the background.  Something about it just intrigues me.  I think it''s the dof of the background which gives a soft sad feel to it.  Truly lovely.</td>', 'This is not an exceptional fence picture (the fence itself that is) but it works so well with the background.  Something about it just intrigues me.  I think it''s the dof of the background which gives a soft sad feel to it.  Truly lovely.', '2008-03-21 18:36:24.000000', NULL, 1),
(4579154, 659333, 41675, '<td valign="top">I like the foreground of your image. The sky is a bit too dark and overpowering though.</td>', 'I like the foreground of your image. The sky is a bit too dark and overpowering though.', '2008-03-21 18:43:28.000000', NULL, 1),
(4579158, 658080, 41675, '<td valign="top">I like the blue sky against the colors of the "natural fencing" Well composed, good balance and just pleasant to look at. Good luck in the challenge.</td>', 'I like the blue sky against the colors of the "natural fencing" Well composed, good balance and just pleasant to look at. Good luck in the challenge.', '2008-03-21 18:44:30.000000', NULL, 1),
(4579163, 658680, 41675, '<td valign="top">I love the pattern, colors and shadows. Good eye to have seen this. Good luck in the challenge!</td>', 'I love the pattern, colors and shadows. Good eye to have seen this. Good luck in the challenge!', '2008-03-21 18:46:47.000000', NULL, 1),
(4579170, 658019, 41675, '<td valign="top">For me, my eyes are continuously drawn away from your image to the very thick black border. I would have given your image a higher score if it was a thinner border. I like the tonal values you chose for your picture.</td>', 'For me, my eyes are continuously drawn away from your image to the very thick black border. I would have given your image a higher score if it was a thinner border. I like the tonal values you chose for your picture.', '2008-03-21 18:50:19.000000', NULL, 1),
(4579233, 658421, 66597, '<td valign="top">This is really pretty with a nice counterpoint to the fence in the foreground. Be careful of those dust spots, though!</td>', 'This is really pretty with a nice counterpoint to the fence in the foreground. Be careful of those dust spots, though!', '2008-03-21 19:19:26.000000', NULL, 1),
(4579236, 659595, 66597, '<td valign="top">I really like the sepia conversion here and the lines. I''m wishing for just a touch shallower DOF, perhaps, as there is a lot going on in this photo.</td>', 'I really like the sepia conversion here and the lines. I''m wishing for just a touch shallower DOF, perhaps, as there is a lot going on in this photo.', '2008-03-21 19:20:09.000000', NULL, 1),
