(4583184, 659334, 61961, '<td valign="top">Is this <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=20168" rel="nofollow" target="_blank">charliebaker</a> again, or an imitator?  I''ll say one thing for these entries -- they provoke a reaction in me.  However, the reaction is about the photographer and not the "photo."  Have fun,</td>', 'Is this  charliebaker again, or an imitator?  I''ll say one thing for these entries -- they provoke a reaction in me.  However, the reaction is about the photographer and not the "photo."  Have fun,', '2008-03-24 11:08:26.000000', NULL, 1),
(4583190, 657765, 15291, '<td valign="top">Nice image. The black spot there in the snow (ridge line) kept catching my eye.</td>', 'Nice image. The black spot there in the snow (ridge line) kept catching my eye.', '2008-03-24 11:11:49.000000', NULL, 1),
(4583195, 658601, 15291, '<td valign="top">Well done. Was a bit to centralized for me. Little left or right would have been better (imho).</td>', 'Well done. Was a bit to centralized for me. Little left or right would have been better (imho).', '2008-03-24 11:13:25.000000', NULL, 1),
(4583269, 659202, 61961, '<td valign="top">Ouch, wrong challenge?  I''ll pass on voting for this one.</td>', 'Ouch, wrong challenge?  I''ll pass on voting for this one.', '2008-03-24 11:47:15.000000', NULL, 1),
(4583368, 659244, 90387, '<td valign="top">Very intersting.  This would have rocked in Patterns!</td>', 'Very intersting.  This would have rocked in Patterns!', '2008-03-24 12:29:59.000000', NULL, 1),
(4583373, 659679, 90387, '<td valign="top">I really like the depth of field, but I''m kinda wishing the corner was''t cut off.  We''ll see what everyone else thinks.</td>', 'I really like the depth of field, but I''m kinda wishing the corner was''t cut off.  We''ll see what everyone else thinks.', '2008-03-24 12:31:11.000000', NULL, 1),
(4583381, 659673, 90387, '<td valign="top">I like the idea, but the blue cast is very overwhleming.</td>', 'I like the idea, but the blue cast is very overwhleming.', '2008-03-24 12:37:50.000000', NULL, 1),
(4583387, 657227, 90387, '<td valign="top">Great job getting a nice bright white in the snow.  Very nice!</td>', 'Great job getting a nice bright white in the snow.  Very nice!', '2008-03-24 12:40:09.000000', NULL, 1),
(4583395, 658818, 90387, '<td valign="top">I really like this, and the moss and lichen make for a good photo.  Greens and yellows might be a touch oversaturated.</td>', 'I really like this, and the moss and lichen make for a good photo.  Greens and yellows might be a touch oversaturated.', '2008-03-24 12:43:16.000000', NULL, 1),
(4583403, 659487, 90387, '<td valign="top">Great job capturing some nice white snow.  Colors are perfect!</td>', 'Great job capturing some nice white snow.  Colors are perfect!', '2008-03-24 12:45:35.000000', NULL, 1),
(4583424, 658460, 90387, '<td valign="top">I really like the rotation and crop on this.  My only issue is that little spiderweb on the bottom right.  My eye keeps going right to it.</td>', 'I really like the rotation and crop on this.  My only issue is that little spiderweb on the bottom right.  My eye keeps going right to it.', '2008-03-24 12:55:18.000000', NULL, 1),
(4583484, 658880, 89333, '<td valign="top">Great light. I would crop out the right between the two shelters.</td>', 'Great light. I would crop out the right between the two shelters.', '2008-03-24 13:52:55.000000', NULL, 1),
(4583487, 659214, 89333, '<td valign="top">Very nice light and interesting geometric pattern. I would crop the top much closer to the fence as the sky is not that interesting.</td>', 'Very nice light and interesting geometric pattern. I would crop the top much closer to the fence as the sky is not that interesting.', '2008-03-24 13:55:23.000000', NULL, 1),
(4583488, 659516, 89333, '<td valign="top">Very nice. I would crop the top to maybe half-way to the umbrella.</td>', 'Very nice. I would crop the top to maybe half-way to the umbrella.', '2008-03-24 13:57:57.000000', NULL, 1),
(4583491, 658567, 89333, '<td valign="top">Nice soft light and colors. I find the branches in the background distracting (due to the bright arches formed). You might be able to crop most of them out.</td>', 'Nice soft light and colors. I find the branches in the background distracting (due to the bright arches formed). You might be able to crop most of them out.', '2008-03-24 14:00:36.000000', NULL, 1),
(4583493, 658950, 89333, '<td valign="top">Very nice. I find the dark stem on the fat right distracting and would crop it out.</td>', 'Very nice. I find the dark stem on the fat right distracting and would crop it out.', '2008-03-24 14:01:39.000000', NULL, 1),
(4583498, 658180, 89333, '<td valign="top">Interesting shot. I find 2 problems: 1) the monkey''s eyes are a bit soft and need to be sharper and 2) the white area area at the upper right is somewhat distracting. (I realize animal shots can be tricky to get everything.)</td>', 'Interesting shot. I find 2 problems: 1) the monkey''s eyes are a bit soft and need to be sharper and 2) the white area area at the upper right is somewhat distracting. (I realize animal shots can be tricky to get everything.)', '2008-03-24 14:04:14.000000', NULL, 1),
(4583504, 659612, 89333, '<td valign="top">Interesting shot. I would crop the left (to a bit to the left of the group of blue and red players) to eliminate the distraction of the light at the far left.</td>', 'Interesting shot. I would crop the left (to a bit to the left of the group of blue and red players) to eliminate the distraction of the light at the far left.', '2008-03-24 14:07:23.000000', NULL, 1),
(4583579, 657748, 88054, '<td valign="top">This is an unusual but interesting angle. The clouds are awesome. Very nice.</td>', 'This is an unusual but interesting angle. The clouds are awesome. Very nice.', '2008-03-24 14:44:48.000000', NULL, 1),
(4583587, 658019, 88054, '<td valign="top">I like the textures in the photo but it''s tough to make out the details in the fence or grass. I like the colors...gives a sorta cold western/frontier feel.</td>', 'I like the textures in the photo but it''s tough to make out the details in the fence or grass. I like the colors...gives a sorta cold western/frontier feel.', '2008-03-24 14:49:42.000000', NULL, 1),
(4583588, 658080, 88054, '<td valign="top">Beautiful flowers.</td>', 'Beautiful flowers.', '2008-03-24 14:50:07.000000', NULL, 1),
(4583591, 659621, 88054, '<td valign="top">I like the way you captured the textures in the post and the rust in the chain.</td>', 'I like the way you captured the textures in the post and the rust in the chain.', '2008-03-24 14:52:11.000000', NULL, 1),
(4583592, 658320, 89333, '<td valign="top">Interesting image. I like the feeling of distance. I think I would crop the right (to near the couple) and the top (a bit above the bridge towers) as much of this space is not adding anything.</td>', 'Interesting image. I like the feeling of distance. I think I would crop the right (to near the couple) and the top (a bit above the bridge towers) as much of this space is not adding anything.', '2008-03-24 14:52:29.000000', NULL, 1),
(4583593, 659218, 79128, '<td valign="top">Seems somewhat blurry perhaps by movement. I like the angle and the idea.</td>', 'Seems somewhat blurry perhaps by movement. I like the angle and the idea.', '2008-03-24 14:52:39.000000', NULL, 1),
(4583594, 659167, 88054, '<td valign="top">Great perspective.</td>', 'Great perspective.', '2008-03-24 14:53:09.000000', NULL, 1),
(4583595, 657765, 79128, '<td valign="top">Very nice capture, the contrast of the clouds with the snow and the darkness of the fence great.</td>', 'Very nice capture, the contrast of the clouds with the snow and the darkness of the fence great.', '2008-03-24 14:54:29.000000', NULL, 1),
(4583599, 657370, 89333, '<td valign="top">Nice idea. I find the background distracting, but you could crop much closer to the fence to eliminate it. I''m guessing you were trying for both eyes to be looking through the holes, but I don''t like the fact that the right eye (of the subject) is cut and would have preferred seeing the whole of that eye in lieu of the second eye.</td>', 'Nice idea. I find the background distracting, but you could crop much closer to the fence to eliminate it. I''m guessing you were trying for both eyes to be looking through the holes, but I don''t like the fact that the right eye (of the subject) is cut and would have preferred seeing the whole of that eye in lieu of the second eye.', '2008-03-24 14:55:45.000000', NULL, 1),
(4583600, 657772, 88054, '<td valign="top">The foreground is a bit dark but that is a beautiful sky.</td>', 'The foreground is a bit dark but that is a beautiful sky.', '2008-03-24 14:55:51.000000', NULL, 1),
(4583604, 659661, 79128, '<td valign="top">Just beautiful!</td>', 'Just beautiful!', '2008-03-24 14:57:10.000000', NULL, 1),
(4583605, 659651, 88054, '<td valign="top">Left side of the shot is a bit dark. Looks like a beautiful place.</td>', 'Left side of the shot is a bit dark. Looks like a beautiful place.', '2008-03-24 14:57:13.000000', NULL, 1),
(4583609, 658853, 89333, '<td valign="top">Very nice. It''s unfortunate this was a basic editing challenge as I find the bright spot in the water distracting. Maybe if you had waited it would have gone away as the waves moved. I think I like the person (?) in the background as it gives some interest.</td>', 'Very nice. It''s unfortunate this was a basic editing challenge as I find the bright spot in the water distracting. Maybe if you had waited it would have gone away as the waves moved. I think I like the person (?) in the background as it gives some interest.', '2008-03-24 14:58:23.000000', NULL, 1),
(4583610, 658681, 79128, '<td valign="top">I like the way the post leans opposite to the hills. Good job</td>', 'I like the way the post leans opposite to the hills. Good job', '2008-03-24 14:58:50.000000', NULL, 1),
(4583612, 659449, 88054, '<td valign="top">I like it. I think I would have preferred a touch more contrast mostly because of the bright background. That might help the fence and bird jump out more. Still well above average for me.</td>', 'I like it. I think I would have preferred a touch more contrast mostly because of the bright background. That might help the fence and bird jump out more. Still well above average for me.', '2008-03-24 15:00:35.000000', NULL, 1),
(4583614, 659620, 89333, '<td valign="top">Nice image. I would have preferred if you had moved to the right a bit so that 1) the fence line didn''t bisect the image and 2) you could see the line of fence mote.</td>', 'Nice image. I would have preferred if you had moved to the right a bit so that 1) the fence line didn''t bisect the image and 2) you could see the line of fence mote.', '2008-03-24 15:02:35.000000', NULL, 1),
(4583616, 659450, 88054, '<td valign="top">Hard to tell this is a fence. That being said...I love the composition, colors and exposure. The textures in the chain and post are great.</td>', 'Hard to tell this is a fence. That being said...I love the composition, colors and exposure. The textures in the chain and post are great.', '2008-03-24 15:03:48.000000', NULL, 1),
(4583617, 659494, 89333, '<td valign="top">Technically it''s fine, but I don''t find anything that''s really strong or anything that leads my eye. It might have been stronger if you had focused on one element in the background, giving a definite point of visual focus.</td>', 'Technically it''s fine, but I don''t find anything that''s really strong or anything that leads my eye. It might have been stronger if you had focused on one element in the background, giving a definite point of visual focus.', '2008-03-24 15:04:42.000000', NULL, 1),
(4583620, 659396, 88054, '<td valign="top">This looks so cold. The sky is gorgeous.</td>', 'This looks so cold. The sky is gorgeous.', '2008-03-24 15:06:12.000000', NULL, 1),
(4583622, 659334, 918, '<td valign="top">Lovely BW Image with very nice use of contrast.</td>', 'Lovely BW Image with very nice use of contrast.', '2008-03-24 15:07:06.000000', NULL, 1),
(4583624, 659673, 89333, '<td valign="top">Nice image. As it is, I find the bright sky very distracting, but cropping both the left and the right eliminates this as well as focus the image more on the fence and makes it much stronger.</td>', 'Nice image. As it is, I find the bright sky very distracting, but cropping both the left and the right eliminates this as well as focus the image more on the fence and makes it much stronger.', '2008-03-24 15:09:31.000000', NULL, 1),
(4583625, 658299, 88054, '<td valign="top">Great composition. Exposure looks near perfect. I would have liked to see just a bit more of the post by using a slightly deeper depth of field. The textures are so interesting I just wish I could see more. Good luck.</td>', 'Great composition. Exposure looks near perfect. I would have liked to see just a bit more of the post by using a slightly deeper depth of field. The textures are so interesting I just wish I could see more. Good luck.', '2008-03-24 15:09:47.000000', NULL, 1),
(4583627, 659495, 88054, '<td valign="top">Lovely.</td>', 'Lovely.', '2008-03-24 15:10:12.000000', NULL, 1),
(4583628, 659239, 67697, '<td valign="top">The change in color in the sky is beautiful.  Also fun that you caught the walking person between the slats.</td>', 'The change in color in the sky is beautiful.  Also fun that you caught the walking person between the slats.', '2008-03-24 15:11:35.000000', NULL, 1),
(4583630, 658623, 67697, '<td valign="top">That''s a sweet capture.  Someone desperately wants to be out there with you.  Those eyes say it all!</td>', 'That''s a sweet capture.  Someone desperately wants to be out there with you.  Those eyes say it all!', '2008-03-24 15:12:18.000000', NULL, 1),
(4583632, 658760, 67697, '<td valign="top">I like how you chose to put the focus on the fallen part of the fence.  It does a nice job with conveying how old and worn the whole thing is.</td>', 'I like how you chose to put the focus on the fallen part of the fence.  It does a nice job with conveying how old and worn the whole thing is.', '2008-03-24 15:13:29.000000', NULL, 1),
(4583635, 659197, 88054, '<td valign="top">Might be slightly over processed but great composition and what a beautiful sky.</td>', 'Might be slightly over processed but great composition and what a beautiful sky.', '2008-03-24 15:14:25.000000', NULL, 1),
(4583637, 659169, 88054, '<td valign="top">Very pretty.</td>', 'Very pretty.', '2008-03-24 15:15:26.000000', NULL, 1),
(4583638, 658529, 88054, '<td valign="top">This is an awesome shot. The moss adds so much texture and depth. Very well done.</td>', 'This is an awesome shot. The moss adds so much texture and depth. Very well done.', '2008-03-24 15:17:56.000000', NULL, 1),
(4583640, 659160, 67697, '<td valign="top">Nice and springy and good lighting too.  Why did you choose to use a smaller image size?  It would be great to have a bigger picture and see all the details.</td>', 'Nice and springy and good lighting too.  Why did you choose to use a smaller image size?  It would be great to have a bigger picture and see all the details.', '2008-03-24 15:18:58.000000', NULL, 1),
(4583641, 659169, 89333, '<td valign="top">Very, very nice. I would have liked it a bit better if the sky was cropped to a bit above the top arch of the fence.</td>', 'Very, very nice. I would have liked it a bit better if the sky was cropped to a bit above the top arch of the fence.', '2008-03-24 15:19:01.000000', NULL, 1),
(4583643, 659669, 88054, '<td valign="top">Interesting use of light and shadows. I would not have guessed it was midnight. Looks more like sunrise/set.</td>', 'Interesting use of light and shadows. I would not have guessed it was midnight. Looks more like sunrise/set.', '2008-03-24 15:20:10.000000', NULL, 1),
(4583645, 659661, 88054, '<td valign="top">I''m not sure why but I really like this...Must be her expression. She looks like she has a story to tell and is just waiting for someone to listen.</td>', 'I''m not sure why but I really like this...Must be her expression. She looks like she has a story to tell and is just waiting for someone to listen.', '2008-03-24 15:23:42.000000', NULL, 1),
(4583763, 659202, 90777, '<td valign="top">I take it this is the environmental portrait submitted to fences by mistake, as mentioned in the forum?  I won''t give it a score as I''m sure you''ll be getting hammered by everyone who doesn''t read the forum.</td>', 'I take it this is the environmental portrait submitted to fences by mistake, as mentioned in the forum?  I won''t give it a score as I''m sure you''ll be getting hammered by everyone who doesn''t read the forum.', '2008-03-24 16:10:15.000000', NULL, 1),
(4583770, 658818, 89333, '<td valign="top">Very nice, soft light. However, I think you need to have the top of the near post.</td>', 'Very nice, soft light. However, I think you need to have the top of the near post.', '2008-03-24 16:13:58.000000', NULL, 1),
(4583773, 659400, 90777, '<td valign="top">What are the faint lines at the top of the fence?</td>', 'What are the faint lines at the top of the fence?', '2008-03-24 16:17:25.000000', NULL, 1),
(4583775, 657772, 90777, '<td valign="top">Nice Sky</td>', 'Nice Sky', '2008-03-24 16:18:04.000000', NULL, 1),
(4584329, 659155, 70000, '<td valign="top">interesting find with the rusted and clean wire. This could use a little pop in the contrast to make it a little more bold, i like the colors a lot.</td>', 'interesting find with the rusted and clean wire. This could use a little pop in the contrast to make it a little more bold, i like the colors a lot.', '2008-03-24 21:35:39.000000', NULL, 1),
