(4587055, 658653, 19799, '<td valign="top">This fence looks important...especially to the two seats it''s behind!</td>', 'This fence looks important...especially to the two seats it''s behind!', '2008-03-25 23:07:30.000000', NULL, 1),
(4587058, 659637, 19799, '<td valign="top">Would hold the fence theme more if the fence was in focus and the buildings in behind it were oof.</td>', 'Would hold the fence theme more if the fence was in focus and the buildings in behind it were oof.', '2008-03-25 23:08:28.000000', NULL, 1),
(4587059, 659331, 19799, '<td valign="top">I like how the fence divides this photo. By using the fence as a dividing line it really brings attention to it.</td>', 'I like how the fence divides this photo. By using the fence as a dividing line it really brings attention to it.', '2008-03-25 23:09:24.000000', NULL, 1),
