(4588004, 659402, 61961, '<td valign="top">It really appears as if this was taken inside a prison.  Very strong elements and the grain really works.  Wish this had done better, but I''m happy to have been one of your 10s.</td>', 'It really appears as if this was taken inside a prison.  Very strong elements and the grain really works.  Wish this had done better, but I''m happy to have been one of your 10s.', '2008-03-26 09:05:03.000000', NULL, 0),
(4588008, 659140, 70514, '<td valign="top">Such a great capture!  Wonderful contrasting colors and textures, spot on composition and dof.  Nothing left to do here, imo.  I guess you must be quite stealth with retrieving your camera during instances like this.  Either that, or maybe you own a stuffed bird and are pulling a fast one on us ;)</td>', 'Such a great capture!  Wonderful contrasting colors and textures, spot on composition and dof.  Nothing left to do here, imo.  I guess you must be quite stealth with retrieving your camera during instances like this.  Either that, or maybe you own a stuffed bird and are pulling a fast one on us ;)', '2008-03-26 09:06:34.000000', NULL, 0),
(4588012, 659516, 70514, '<td valign="top">Almost voyeristic... I like that they''re hiding from you a bit, leaves a bit to my imagination.</td>', 'Almost voyeristic... I like that they''re hiding from you a bit, leaves a bit to my imagination.', '2008-03-26 09:08:53.000000', NULL, 0),
